/* app.admin.js — Sky LIS Super Admin Portal (platform operator) */
'use strict';
Object.assign(DB, PDB); // platform data lives in the shared store for the admin build
const R1 = window.SCOPE === 'r1'; // release-1 scope: everything except the integration library (serves deferred client modules)
App.portal = 'admin'; App.version = R1 ? 'v3.1 · release 1 scope' : 'v3';
App.user = { name: 'Ahmed Nasser', nameAr: 'أحمد ناصر', role: 'Super Admin', roleAr: 'مدير النظام', initials: 'AN' };
App.tenant = null; App.branch = null; App.currency = 'EGP';
DB.notifications = DB.notifications;

/* ---------- navigation ---------- */
App.nav = [
  { g: 'overview', items: [{ k: 'home', l: 'home', i: 'home' }, { k: 'dashboard', l: 'dashboard', i: 'chart' }] },
  { g: 'administration', items: [{ k: 'clients', l: 'clients', i: 'briefcase' }, { k: 'subscriptions', l: 'subscriptionsWallets', i: 'wallet' }, { k: 'adminRoles', l: 'roles', i: 'shield' }, { k: 'adminUsers', l: 'adminUsers', i: 'users' }, { k: 'sessions', l: 'sessions', i: 'monitor' }, { k: 'auditLog', l: 'auditLog', i: 'clipboard' }] },
  { g: 'masterData', items: [{ k: 'countries', l: 'countries', i: 'globe' }, { k: 'governorates', l: 'governorates', i: 'pin' }, { k: 'clinicalGroups', l: 'clinicalGroups', i: 'layers' }, { k: 'services', l: 'services', i: 'list' }, { k: 'tests', l: 'tests', i: 'flask' }, { k: 'serviceSequence', l: 'serviceSequence', i: 'hash' }, { k: 'sampleTypes', l: 'sampleTypes', i: 'tube' }, { k: 'units', l: 'unitsOfMeasure', i: 'sliders' }, { k: 'patientConditions', l: 'patientConditions', i: 'user' }, { k: 'preparations', l: 'preparations', i: 'help' }, { k: 'comments', l: 'commentLibrary', i: 'msg' }, { k: 'reasons', l: 'reasons', i: 'tag' }, { k: 'diagnoses', l: 'diagnoses', i: 'book' }, { k: 'additionalServices', l: 'additionalServices', i: 'star' }, { k: 'reportTemplates', l: 'reportTemplates', i: 'file' }, { k: 'testRules', l: 'testRules', i: 'link' }, { k: 'shortcutSets', l: 'shortcutSets', i: 'zap' }] },
  { g: 'microbiology', items: [{ k: 'drugTypes', l: 'drugTypes', i: 'box' }, { k: 'commercialNames', l: 'commercialNames', i: 'tag' }, { k: 'antibiotics', l: 'antibiotics', i: 'droplet' }, { k: 'organisms', l: 'organisms', i: 'bug' }, { k: 'sensitivities', l: 'sensitivityValues', i: 'sliders' }] },
  { g: 'integrationLibrary', items: [{ k: 'analyzerModels', l: 'analyzerModels', i: 'cpu' }, { k: 'pcrKits', l: 'pcrKits', i: 'dna' }, { k: 'codeSystems', l: 'codeSystems', i: 'hash' }, { k: 'ruleTemplates', l: 'ruleTemplates', i: 'zap' }] },
  { g: 'platform', items: [{ k: 'platformParams', l: 'platformParameters', i: 'settings' }, { k: 'notificationTemplates', l: 'notificationTemplates', i: 'send' }, { k: 'profile', l: 'profile', i: 'user' }] }
];
if (R1) App.nav = App.nav.filter(g => g.g !== 'integrationLibrary');
const ADMIN_SCREENS = () => App.nav.flatMap(g => g.items.filter(i => !['home', 'profile'].includes(i.k)).map(i => ({ k: i.k, l: i.l, g: g.g })));

/* ---------- screens ---------- */
App.screens.home = () => `<div class="home-logo"><div class="card"><img src="${LOGO}" alt="Sky LIS"><div class="center muted mt">${t('superAdminPortal')} · ${t('welcomeBack')}, ${esc(L(App.user))}</div></div></div>`;
App.screens.dashboard = () => {
  const p = App.store.dashPeriod || '7'; const m = { '7': { l: t('last7'), patients: '6,842', tests: '31,406', regs: '8,921', bars: [92, 78, 65, 58, 44, 36, 27] }, '30': { l: t('last30'), patients: '27,914', tests: '127,820', regs: '36,440', bars: [86, 81, 72, 61, 48, 43, 34] }, '90': { l: t('last90'), patients: '84,506', tests: '386,024', regs: '108,775', bars: [95, 88, 79, 70, 60, 49, 41] } }[p];
  const active = DB.clients.filter(c => c.status === 'Active').length;
  return pageHead(t('dashboard'), `${t('superAdminPortal')} / ${t('dashboard')}`, `<select class="inp sm" onchange="App.store.dashPeriod=this.value;renderMain()"><option value="7" ${p === '7' ? 'selected' : ''}>${t('last7')}</option><option value="30" ${p === '30' ? 'selected' : ''}>${t('last30')}</option><option value="90" ${p === '90' ? 'selected' : ''}>${t('last90')}</option></select><button class="btn" onclick="renderMain()">${ic('refresh')} ${t('refresh')}</button>`) +
    `<div class="kpis">${kpi(t('clients'), DB.clients.length, `${active} ${t('st_Active')} · ${DB.clients.length - active} ${t('st_Inactive')}`, 'briefcase')}${kpi(t('adminUsers'), DB.adminUsers.length, t('allAdminUsers'), 'users')}${kpi(t('servedPatients'), m.patients, m.l, 'user')}${kpi(t('tests'), m.tests, m.l, 'flask')}${kpi(t('registrations'), m.regs, m.l, 'clipboard')}${kpi(t('walletBelowZero'), DB.clients.filter(c => c.wallet <= 0).length, t('needsTopUp'), 'wallet', 'bad')}</div>
<div class="dash-grid">${card({ title: t('registrationsByClient'), sub: m.l, body: barChart(m.bars, ['Al Noor', 'MedLine', 'Prime', 'Delta', 'LifeCheck', 'Cura', 'BioLab']) })}${card({ title: t('clientsOverview'), body: `<div class="kv"><dt>${t('st_Active')}</dt><dd>${active}</dd><dt>${t('st_Inactive')}</dt><dd>${DB.clients.length - active}</dd><dt>${t('bySubscription')}</dt><dd>${DB.clients.filter(c => c.source === 'Subscription').length}</dd><dt>${t('byManual')}</dt><dd>${DB.clients.filter(c => c.source === 'Manual').length}</dd><dt>${t('plans')}</dt><dd>${DB.plans.map(pl => `${pl.name}: ${DB.clients.filter(c => c.plan === pl.name).length}`).join(' · ')}</dd></div>` })}</div>
${card({ title: t('recentClients'), actions: `<button class="link" onclick="navigate('clients')">${t('viewAll')}</button>`, flush: true, body: grid({ cols: [{ k: 'name', l: 'clientName', f: r => `<b>${esc(r.name)}</b><div class="small muted">${esc(r.url)}</div>` }, { k: 'country', l: 'country' }, { k: 'plan', l: 'plan' }, { k: 'wallet', l: 'wallet', f: r => money(r.wallet) }, { k: 'created', l: 'created' }, { k: 'source', l: 'source', f: r => sb(r.source) }, { k: 'status', l: 'status', f: r => sb(r.status) }], rows: DB.clients.slice(0, 5), nofoot: true }) })}`;
};
App.screens.clients = { key: 'clients', group: 'administration', title: 'clients', singular: 'client', data: 'clients', wide: true, note: 'clientsNote', filters: [{ k: 'source', l: 'source', opts: ['Subscription', 'Manual'] }, { k: 'plan', l: 'plan', opts: () => DB.plans.map(p => [p.name, p.name]) }],
  cols: [{ k: 'name', l: 'clientName', f: r => `<b>${esc(r.name)}</b><div class="small muted">${esc(r.url)}</div>` }, { k: 'country', l: 'country', f: r => `${esc(r.country)} · ${esc(r.gov)}` }, { k: 'manager', l: 'manager', f: r => `${esc(r.manager)}<div class="small muted">${esc(r.managerMobile)}</div>` }, { k: 'plan', l: 'plan' }, { k: 'wallet', l: 'wallet', f: r => money(r.wallet) }, { k: 'branches', l: 'branches', w: '70px' }, { k: 'users', l: 'users', w: '60px' }, { k: 'created', l: 'created' }, { k: 'source', l: 'source', f: r => sb(r.source) }, { k: 'status', l: 'status', f: r => sb(r.status) }],
  fields: [{ k: 'name', l: 'clientName', req: true }, { k: 'nameAr', l: 'arabicName' }, { k: 'country', l: 'country', type: 'select', req: true, opts: () => DB.countries.map(c => [c.name, c.name]) }, { k: 'gov', l: 'governorate', type: 'select', req: true, opts: () => DB.governorates.map(g => [g.name, g.name]) }, { k: 'address', l: 'address', req: true, span: 2 }, { k: 'mobile', l: 'mobile', req: true, help: 'countryCodeHelp' }, { k: 'licence', l: 'medicalLicence' }, { k: 'manager', l: 'managerName', req: true }, { k: 'managerMobile', l: 'managerMobile', req: true }, { k: 'email', l: 'email', type: 'email' }, { k: 'plan', l: 'plan', type: 'select', req: true, opts: () => DB.plans.map(p => [p.name, p.name]) }, { k: 'url', l: 'portalUrl', help: 'urlHelp' }, statusField],
  rowActions: r => rowBtn('key', 'resetPassword', `toast(t('resetSent'),'ok','${esc(r.manager)} · ${esc(r.managerMobile)}')`) + rowBtn('wallet', 'wallet', `navigate('subscriptions',{client:${r.id}})`) + rowBtn(r.status === 'Active' ? 'lock' : 'unlock', r.status === 'Active' ? 'deactivate' : 'activate', `toggleClient(${r.id})`),
  onCreate: o => { o.created = '2026-10-08'; o.source = 'Manual'; o.wallet = 0; o.branches = 1; o.users = 1; o.url = o.url || (o.name.toLowerCase().replace(/[^a-z0-9]+/g, '').slice(0, 12) + '.skylis.demo'); toast(t('clientCreatedCopy'), 'ok'); } };
function toggleClient(id) { const c = byId(DB.clients, id); c.status = c.status === 'Active' ? 'Inactive' : 'Active'; renderMain(); toast(`${c.name}: ${t('st_' + c.status)}`, c.status === 'Active' ? 'ok' : 'warn', c.status === 'Inactive' ? t('clientBlocked') : ''); }
App.screens.subscriptions = (p) => {
  const sel = p.client || App.store.subClient || 1; App.store.subClient = sel; const c = byId(DB.clients, sel); const tx = DB.walletTx.filter(x => x.client === sel);
  return pageHead(t('subscriptionsWallets'), `${t('administration')} / ${t('subscriptionsWallets')}`, `<button class="btn primary" onclick="topUp(${sel})">${ic('plus')} ${t('topUp')}</button>`) +
    `<div class="grid2">${card({ title: t('plans'), flush: true, body: grid({ cols: [{ k: 'name', l: 'plan' }, { k: 'monthly', l: 'monthlyFee', f: r => money(r.monthly) }, { k: 'branches', l: 'branches' }, { k: 'users', l: 'users' }, { k: 'sms', l: 'smsQuota' }, { k: 'analyzers', l: 'analyzers' }], rows: DB.plans, nofoot: true }) })}
${card({ title: t('clientWallet'), sub: t('walletMeaning'), body: `<div class="field"><label>${t('client')}</label><select class="inp" onchange="navigate('subscriptions',{client:Number(this.value)})">${DB.clients.map(x => `<option value="${x.id}" ${x.id === sel ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select></div><div class="kpis mt">${kpi(t('walletBalance'), money(c.wallet), c.plan, 'wallet', c.wallet <= 0 ? 'bad' : 'ok')}${kpi(t('monthlyFee'), money(byId(DB.plans, DB.plans.find(p => p.name === c.plan)?.id)?.monthly || 0), t('nextCharge') + ' 2026-11-05', 'calendar')}</div>` })}</div>
${card({ title: t('walletTransactions'), flush: true, body: grid({ cols: [{ k: 'date', l: 'date' }, { k: 'type', l: 'type', f: r => badge(r.type, r.amount > 0 ? 'ok' : 'muted') }, { k: 'amount', l: 'amount', f: r => `<span class="${r.amount < 0 ? 'muted' : ''}">${money(r.amount)}</span>` }, { k: 'ref', l: 'reference' }, { k: 'user', l: 'user' }], rows: tx }) })}`;
};
function topUp(client) { modal({ title: t('topUp'), size: 'sm', body: formGrid([{ k: 'amount', l: 'amount', type: 'number', req: true, val: 5000 }, { k: 'ref', l: 'reference', req: true, val: 'INV-2026-' + Math.floor(Math.random() * 9000 + 1000) }], {}, ''), foot: `<button class="btn" onclick="closeModal()">${t('cancel')}</button><button class="btn primary" onclick="(function(){if(!validateForm())return;const o=readForm();const c=byId(DB.clients,${client});c.wallet+=Number(o.amount);DB.walletTx.unshift({id:Date.now(),client:${client},date:'2026-10-08',type:'Top-up',amount:Number(o.amount),ref:o.ref,user:'Ahmed Nasser'});closeModal();renderMain();toast(t('walletUpdated'),'ok')})()">${t('confirm')}</button>` }); }
App.screens.adminRoles = { key: 'adminRoles', group: 'administration', title: 'roles', singular: 'role', data: 'adminRoles', size: 'xl', cols: [{ k: 'name', l: 'roleName' }, { k: 'desc', l: 'description' }, { k: 'users', l: 'usersCount', w: '90px' }, { k: 'screens', l: 'screenAccess', f: r => r.screens === 'all' ? badge(t('allScreens'), 'violet') : badge(Object.keys(r.screens).length + ' ' + t('screens'), 'info') }, { k: 'status', l: 'status', f: r => sb(r.status) }], editor: row => roleEditor(row, ADMIN_SCREENS(), { results: false, discountCap: false, specialFilter: x => ['Impersonate client admin', 'Reset client password', 'Activate client', 'Expire User Password', 'Change Password'].includes(x) }), read: root => readRole(root), refCheck: r => r.users > 0 ? t('roleHasUsers') : null, onCreate: o => { o.users = 0; } };
App.screens.adminUsers = { key: 'adminUsers', group: 'administration', title: 'adminUsers', singular: 'adminUser', data: 'adminUsers', wide: true, cols: [{ k: 'name', l: 'fullName' }, { k: 'username', l: 'username' }, { k: 'mobile', l: 'mobile' }, { k: 'email', l: 'email' }, { k: 'role', l: 'role', f: r => esc(byId(DB.adminRoles, r.role)?.name) }, { k: 'locked', l: 'locked', f: r => sb(r.locked ? 'Locked' : 'Unlocked') }, { k: 'expiry', l: 'passwordExpiry', f: r => r.expiry || '—' }, { k: 'status', l: 'status', f: r => sb(r.status) }],
  fields: [{ k: 'name', l: 'fullName', req: true }, { k: 'username', l: 'username', req: true, help: 'usernameHelp' }, { k: 'mobile', l: 'mobile', req: true, help: 'countryCodeHelp' }, { k: 'email', l: 'email', type: 'email' }, { k: 'role', l: 'role', type: 'select', req: true, opts: () => DB.adminRoles.filter(r => r.status === 'Active').map(r => [r.id, r.name]) }, { k: 'expiry', l: 'passwordExpiry', type: 'date' }, { k: 'password', l: 'password', type: 'password', req: true }, { k: 'confirm', l: 'confirmPassword', type: 'password', req: true }, { k: 'locked', l: 'locked', type: 'toggle', onLabel: 'st_Locked', offLabel: 'st_Unlocked' }, statusField, { k: 'note', l: 'privileges', type: 'static', html: t('inheritedFromRole'), span: 2 }],
  beforeSave: o => { if (!/^[a-z0-9._]{4,30}$/i.test(o.username)) return t('usernameHelp'); if (o.password !== o.confirm) return t('passwordMismatch'); if (!/^(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[^\w\s]).{8,}$/.test(o.password)) return t('passwordPolicy'); delete o.confirm; delete o.password; o.role = Number(o.role); return null; }, read: root => { const o = readForm(root); return o; }, refCheck: r => r.id === 1 ? t('mainAdminProtected') : null, onCreate: o => { o.initials = o.name.split(' ').map(x => x[0]).slice(0, 2).join('').toUpperCase(); } };
App.screens.sessions = { key: 'sessions', group: 'administration', title: 'sessions', singular: 'session', data: 'sessions', canAdd: false, canEdit: false, noStatus: true, rows: () => DB.sessions, cols: [{ k: 'user', l: 'user' }, { k: 'ip', l: 'ipAddress' }, { k: 'since', l: 'since', f: r => fmtDT(r.since) }, { k: 'status', l: 'status', f: r => sb(r.status) }], rowActions: r => rowBtn('logout', 'terminateSession', `DB.sessions=DB.sessions.filter(x=>x.id!==${r.id});renderMain();toast(t('sessionTerminated'),'ok')`, 'danger'), canDelete: false };
App.screens.auditLog = { key: 'auditLog', group: 'administration', title: 'auditLog', singular: 'entry', data: 'auditLog', canAdd: false, canEdit: false, canDelete: false, noStatus: true, rows: () => DB.auditLog, cols: [{ k: 'time', l: 'time', f: r => fmtDT(r.time) }, { k: 'user', l: 'user' }, { k: 'action', l: 'action', f: r => badge(r.action, 'info') }, { k: 'entity', l: 'entity' }, { k: 'detail', l: 'details' }, { k: 'client', l: 'client', f: r => esc(byId(DB.clients, r.client)?.name || t('platform')) }] };
// shared master data
for (const k of ['countries', 'governorates', 'groups', 'services', 'tests', 'serviceSequence', 'sampleTypes', 'units', 'patientConditions', 'preparations', 'comments', 'reasons', 'diagnoses', 'additionalServices', 'reportTemplates', 'testRules', 'shortcutSets', 'drugTypes', 'commercialNames', 'antibiotics', 'organisms', 'sensitivities']) { const cfg = SH[k]('masterData'); App.screens[cfg.key] = cfg; }
App.screens.clinicalGroups.note = 'globalMasterNote'; App.screens.services.note = 'globalMasterNote'; App.screens.tests.note = 'globalMasterNote';
App.screens.analyzerModels = { key: 'analyzerModels', group: 'integrationLibrary', title: 'analyzerModels', singular: 'analyzerModel', data: 'analyzerModels', rows: () => DB.analyzerModels, cols: [{ k: 'vendor', l: 'vendor' }, { k: 'model', l: 'model' }, { k: 'discipline', l: 'discipline' }, { k: 'protocol', l: 'protocol' }, { k: 'link', l: 'physicalLink' }, { k: 'modes', l: 'modes' }, { k: 'driver', l: 'driver' }, { k: 'status', l: 'status', f: r => sb(r.status) }], fields: [{ k: 'vendor', l: 'vendor', req: true }, { k: 'model', l: 'model', req: true }, { k: 'discipline', l: 'discipline', type: 'select', req: true, opts: ['Haematology', 'Chemistry', 'Immunology', 'Coagulation', 'Microbiology', 'PCR', 'Urinalysis'] }, { k: 'protocol', l: 'protocol', type: 'select', req: true, opts: ['ASTM', 'ASTM / LIS2-A2', 'HL7 v2', 'File (Excel/CSV)', 'Proprietary'] }, { k: 'link', l: 'physicalLink', type: 'select', opts: ['Serial', 'TCP', 'Serial / TCP', 'Share'] }, { k: 'modes', l: 'modes', help: 'modesHelp' }, { k: 'driver', l: 'driver' }, statusField] };
App.screens.pcrKits = { key: 'pcrKits', group: 'integrationLibrary', title: 'pcrKits', singular: 'pcrKit', data: 'pcrKits', wide: true, cols: [{ k: 'name', l: 'kit' }, { k: 'instrument', l: 'instrument' }, { k: 'valueCol', l: 'valueColumn' }, { k: 'genes', l: 'genes', f: r => r.genes.map(g => `<span class="tag">${esc(g.gene)} ≤${g.pos}</span>`).join('') }, { k: 'status', l: 'status', f: r => sb(r.status) }], editor: row => pcrKitEditor(row), read: root => readPcrKit(root), rowActions: r => rowBtn('eye', 'view', `showPcrKit(${r.id})`) };
function pcrKitEditor(r) { r = r || {}; const genes = r.genes && r.genes.length ? r.genes : [{ dye: 'FAM', gene: '', pos: 38, bl: 40 }]; return formGrid([{ k: 'name', l: 'kit', req: true }, { k: 'instrument', l: 'instrument', req: true }, { k: 'serialLock', l: 'serialLock', help: 'serialLockHelp' }, { k: 'valueCol', l: 'valueColumn', type: 'select', opts: ['Cq', 'CT'] }, { k: 'sheet', l: 'runFileLayout', span: 2 }, statusField], r) + `<div class="section-title">${t('geneThresholds')}</div><div class="table-wrap"><table class="g compact"><thead><tr><th>${t('dye')}</th><th>${t('gene')}</th><th>${t('positiveCt')}</th><th>${t('borderlineCt')}</th><th></th></tr></thead><tbody id="geneRows">${genes.map(geneRow).join('')}</tbody></table></div><button class="btn sm" onclick="el('#geneRows').insertAdjacentHTML('beforeend',geneRow({dye:'',gene:'',pos:38,bl:40}))">${ic('plus', 14)} ${t('addGene')}</button><div class="section-title">${t('verdictRules')}</div><textarea class="inp" id="verdictRows" rows="4">${esc((r.verdicts || [['≥ 2 target genes positive', 'DETECTED'], ['1 target gene positive, or any borderline', 'Presumptive positive'], ['No target positive, IC positive', 'NOT DETECTED'], ['All genes negative incl. IC', 'INVALID — repeat']]).map(v => v.join(' => ')).join('\n'))}</textarea><div class="help">${t('verdictHelp')}</div>`; }
const geneRow = g => `<tr><td><input class="inp sm" value="${esc(g.dye)}" style="width:90px"></td><td><input class="inp sm" value="${esc(g.gene)}" style="width:120px"></td><td><input class="inp sm" type="number" step="any" value="${g.pos}" style="width:70px"></td><td><input class="inp sm" type="number" step="any" value="${g.bl ?? ''}" style="width:70px"></td><td>${rowBtn('trash', 'delete', 'this.closest(\'tr\').remove()', 'danger')}</td></tr>`;
function readPcrKit(root) { const o = readForm(root); o.genes = els('#geneRows tr').map(tr => { const i = tr.querySelectorAll('input'); return { dye: i[0].value, gene: i[1].value, pos: Number(i[2].value), bl: i[3].value === '' ? null : Number(i[3].value) }; }).filter(g => g.gene); o.verdicts = (el('#verdictRows').value || '').split('\n').map(l => l.split('=>').map(s => s.trim())).filter(v => v.length === 2); if (!o.genes.length) { toast(t('kitNeedsGene'), 'error'); return false; } o.folders = o.folders || {}; return o; }
function showPcrKit(id) { const k = byId(DB.pcrKits, id); modal({ title: k.name, size: 'lg', body: `<div class="kv"><dt>${t('instrument')}</dt><dd>${esc(k.instrument)}</dd><dt>${t('serialLock')}</dt><dd class="mono">${esc(k.serialLock)}</dd><dt>${t('runFileLayout')}</dt><dd>${esc(k.sheet)} · ${esc(k.valueCol)}</dd></div><div class="section-title">${t('geneThresholds')}</div><table class="g compact"><thead><tr><th>${t('dye')}</th><th>${t('gene')}</th><th>${t('positive')}</th><th>${t('borderline')}</th><th>${t('negative')}</th></tr></thead><tbody>${k.genes.map(g => `<tr><td>${esc(g.dye)}</td><td>${esc(g.gene)}</td><td>Ct ≤ ${g.pos}</td><td>${g.bl ? `> ${g.pos} – ≤ ${g.bl}` : '—'}</td><td>N/A, 0 or > ${g.bl || g.pos}</td></tr>`).join('')}</tbody></table><div class="section-title">${t('verdictRules')}</div><table class="g compact"><tbody>${k.verdicts.map(v => `<tr><td>${esc(v[0])}</td><td>${badge(v[1], v[1].startsWith('DET') ? 'bad' : v[1].startsWith('NOT') ? 'ok' : v[1].startsWith('INV') ? 'muted' : 'warn')}</td></tr>`).join('')}</tbody></table><div class="section-title">${t('folders')}</div><div class="code">ResultFolder = ${esc(k.folders.result)}\nBackupFolder = ${esc(k.folders.backup)}\nFailedFolder = ${esc(k.folders.failed)}</div>`, foot: `<button class="btn" onclick="closeModal()">${t('close')}</button>` }); }
App.screens.codeSystems = { key: 'codeSystems', group: 'integrationLibrary', title: 'codeSystems', singular: 'codeSystem', data: 'codeSystems', rows: () => DB.codeSystems, cols: [{ k: 'name', l: 'name' }, { k: 'version', l: 'version' }, { k: 'items', l: 'items', f: r => r.items.toLocaleString() }, { k: 'use', l: 'usedFor' }, { k: 'status', l: 'status', f: r => sb(r.status) }], fields: [{ k: 'name', l: 'name', req: true }, { k: 'version', l: 'version', req: true }, { k: 'items', l: 'items', type: 'number' }, { k: 'use', l: 'usedFor' }, statusField], headActions: () => `<button class="btn" onclick="toast(t('importStarted'),'ok','LOINC 2.78 — 104,200 rows')">${ic('upload')} ${t('importCodes')}</button>` };
App.screens.ruleTemplates = { key: 'ruleTemplates', group: 'integrationLibrary', title: 'ruleTemplates', singular: 'ruleTemplate', data: 'ruleTemplates', note: 'ruleTemplatesNote', cols: [{ k: 'name', l: 'name' }, { k: 'group', l: 'clinicalGroup' }, { k: 'formula', l: 'formula', f: r => `<span class="mono small">${esc(r.formula)}</span>` }, { k: 'desc', l: 'description' }, { k: 'status', l: 'status', f: r => sb(r.status) }], fields: [{ k: 'name', l: 'name', req: true }, { k: 'group', l: 'clinicalGroup' }, { k: 'formula', l: 'formula', req: true, span: 2, help: 'ruleSyntaxHelp' }, { k: 'desc', l: 'description', span: 2 }, statusField] };
