App.screens.platformParams = () => pageHead(t('platformParameters'), `${t('platform')} / ${t('platformParameters')}`, `<button class="btn primary" onclick="toast(t('saved'),'ok')">${ic('save')} ${t('save')}</button>`) + card({ title: t('security'), body: formGrid([{ k: 'otpLength', l: 'otpLength', type: 'number', val: DB.platformParams.otpLength }, { k: 'otpMinutes', l: 'otpValidity', type: 'number', val: DB.platformParams.otpMinutes }, { k: 'passwordMinLength', l: 'passwordMinLength', type: 'number', val: 8 }, { k: 'sessionTimeout', l: 'sessionTimeoutMin', type: 'number', val: 30 }], {}, 'four') }) + card({ title: t('tenantsDefaults'), body: formGrid([{ k: 'trialDays', l: 'trialDays', type: 'number', val: 14 }, { k: 'defaultCurrency', l: 'defaultCurrency', val: 'EGP' }, { k: 'defaultLanguage', l: 'defaultLanguage', type: 'select', opts: ['Both', 'English', 'Arabic'], val: 'Both' }, { k: 'masterDataPolicy', l: 'masterDataPolicy', type: 'select', opts: ['No automatic updates', 'Optional pull by tenant', 'Propose updates (tenant approves)'], val: DB.platformParams.masterDataPolicy, span: 2, help: 'masterPolicyHelp' }, { k: 'defaultDelayThresholds', l: 'delayThresholds', val: '70 / 85 / 100', help: 'delayThresholdsHelp' }, { k: 'defaultDiscountCap', l: 'discountCap', type: 'number', val: 10 }], {}, 'four') });
