/* ---------- auth ---------- */
function renderAuth(mode) {
  App.authMode = mode; el('#auth').classList.remove('hidden');
  el('#auth').innerHTML = `<div class="auth"><div class="auth-art"><div><div class="logo-card"><img src="${LOGO}" style="width:100%" alt="Sky LIS"></div></div><div><h1>${t('adminHero')}</h1><p>${t('adminHeroText')}</p><div class="pills"><span class="pill">${t('clients')}</span><span class="pill">${t('masterData')}</span><span class="pill">${t('integrationLibrary')}</span><span class="pill">${t('auditLog')}</span></div></div><div class="small" style="opacity:.75">© 2026 National Technology · Sky LIS ${t('superAdminPortal')}</div></div>
<div class="auth-panel"><div class="auth-card"><div class="row" style="justify-content:flex-end;margin-bottom:10px"><button class="lang-btn" onclick="setLang('${App.lang === 'en' ? 'ar' : 'en'}')">${ic('globe', 13)} ${App.lang === 'en' ? 'العربية' : 'English'}</button></div><div class="lab-lockup"><div class="mark">NT</div><div><h2 style="margin:0">${t('superAdminPortal')}</h2><span class="muted small">National Technology</span></div></div><h2>${t('welcomeBack')}</h2><div class="sub">${t('adminLoginSub')}</div>
<div class="field" id="fUser"><label>${t('username')} <span class="req">*</span></label><input class="inp" id="loginUser" value="admin"><div class="val-msg">${t('username')} ${t('required')}</div></div>
<div class="field mt" id="fPass"><label>${t('password')} <span class="req">*</span></label><div class="row" style="flex-wrap:nowrap"><input class="inp" id="loginPass" type="password" value="Sky@2026" onkeydown="if(event.key==='Enter')doLogin()"><button class="icon-btn" onclick="const p=el('#loginPass');p.type=p.type==='password'?'text':'password'">${ic('eye')}</button></div></div>
<button class="btn primary mt" style="width:100%;justify-content:center" onclick="doLogin()">${ic('arrow')} ${t('login')}</button><div class="info mt">${t('demoCredentials')}</div></div></div></div>`;
}
function doLogin() { const u = el('#loginUser').value.trim(), p = el('#loginPass').value; el('#fUser').classList.toggle('invalid', !u); el('#fPass').classList.toggle('invalid', !p); if (!u || !p) return; el('#auth').classList.add('hidden'); el('#app').classList.remove('hidden'); App.booted = true; App.screen = 'home'; renderShell(); }
if (R1) ['analyzerModels', 'pcrKits', 'codeSystems', 'ruleTemplates'].forEach(k => delete App.screens[k]);
renderAuth('login');
